BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_amenity" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "icon" varchar(50) NOT NULL, "description" varchar(300) NOT NULL, "order" integer NOT NULL);
CREATE TABLE "core_brochureimage" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "order" integer NOT NULL, "caption" varchar(200) NOT NULL);
CREATE TABLE "core_buildingflat" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "tower" varchar(10) NOT NULL, "floor" integer NOT NULL, "flat_number" varchar(20) NOT NULL, "status" varchar(20) NOT NULL, "flat_type_id" bigint NOT NULL REFERENCES "core_flattype" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_chatbotqa" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "question" varchar(500) NOT NULL, "answer" text NOT NULL, "keywords" varchar(500) NOT NULL, "is_active" bool NOT NULL, "order" integer NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "core_flattype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(50) NOT NULL, "bhk" decimal NOT NULL, "carpet_area" varchar(50) NOT NULL, "price" decimal NOT NULL, "price_per_sqft" decimal NOT NULL, "description" text NOT NULL, "is_available" bool NOT NULL, "order" integer NOT NULL, "buildup_area" varchar(50) NOT NULL, "super_buildup_area" varchar(50) NOT NULL, "terrace_area" varchar(50) NOT NULL);
CREATE TABLE "core_lead" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "phone" varchar(20) NOT NULL, "flat_preference" varchar(50) NOT NULL, "message" text NOT NULL, "source" varchar(50) NOT NULL, "created_at" datetime NOT NULL, "is_contacted" bool NOT NULL, "email" varchar(254) NOT NULL, "popup_ad_id" bigint NULL REFERENCES "core_popupad" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "core_popupad" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(200) NOT NULL, "image" varchar(100) NULL, "description" text NOT NULL, "flat_type" varchar(50) NOT NULL, "link" varchar(200) NOT NULL, "is_active" bool NOT NULL, "is_external" bool NOT NULL, "project_logo" varchar(100) NULL, "created_at" datetime NOT NULL, "end_date" date NULL, "start_date" date NULL, "order" integer NOT NULL);
CREATE TABLE "core_projectinfo" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "tagline" varchar(500) NOT NULL, "description" text NOT NULL, "address" text NOT NULL, "city" varchar(100) NOT NULL, "state" varchar(100) NOT NULL, "pincode" varchar(10) NOT NULL, "phone" varchar(20) NOT NULL, "email" varchar(254) NOT NULL, "website" varchar(200) NOT NULL, "map_embed_url" varchar(200) NOT NULL, "facebook" varchar(200) NOT NULL, "instagram" varchar(200) NOT NULL, "twitter" varchar(200) NOT NULL, "youtube" varchar(200) NOT NULL, "director_name" varchar(200) NOT NULL, "director_title" varchar(200) NOT NULL, "director_bio" text NOT NULL, "rera_number" varchar(100) NOT NULL, "total_units" integer NOT NULL, "total_floors" integer NOT NULL, "total_towers" integer NOT NULL, "project_area" varchar(100) NOT NULL, "possession_date" varchar(100) NOT NULL);
CREATE TABLE "core_review" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "rating" integer NOT NULL, "comment" text NOT NULL, "designation" varchar(100) NOT NULL, "is_approved" bool NOT NULL, "created_at" datetime NOT NULL);
CREATE TABLE "core_sitevisitor" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "ip_address" char(39) NOT NULL, "user_agent" text NOT NULL, "page_visited" varchar(500) NOT NULL, "visited_at" datetime NOT NULL);
CREATE TABLE "core_villaplot" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "villa_no" integer NOT NULL UNIQUE, "status" varchar(20) NOT NULL, "owner_name" varchar(200) NOT NULL, "sold_at" datetime NULL, "notes" text NOT NULL, "reserved_by" varchar(200) NOT NULL, "reserved_until" datetime NULL, "completion_pct" integer NOT NULL);
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE UNIQUE INDEX "auth_group_permissions_group_id_permission_id_0cd325b0_uniq" ON "auth_group_permissions" ("group_id", "permission_id");
CREATE INDEX "auth_group_permissions_group_id_b120cbf9" ON "auth_group_permissions" ("group_id");
CREATE INDEX "auth_group_permissions_permission_id_84c5c92e" ON "auth_group_permissions" ("permission_id");
CREATE UNIQUE INDEX "auth_user_groups_user_id_group_id_94350c0c_uniq" ON "auth_user_groups" ("user_id", "group_id");
CREATE INDEX "auth_user_groups_user_id_6a12ed8b" ON "auth_user_groups" ("user_id");
CREATE INDEX "auth_user_groups_group_id_97559544" ON "auth_user_groups" ("group_id");
CREATE UNIQUE INDEX "auth_user_user_permissions_user_id_permission_id_14a6b632_uniq" ON "auth_user_user_permissions" ("user_id", "permission_id");
CREATE INDEX "auth_user_user_permissions_user_id_a95ead1b" ON "auth_user_user_permissions" ("user_id");
CREATE INDEX "auth_user_user_permissions_permission_id_1fbb5f2c" ON "auth_user_user_permissions" ("permission_id");
CREATE INDEX "django_admin_log_content_type_id_c4bce8eb" ON "django_admin_log" ("content_type_id");
CREATE INDEX "django_admin_log_user_id_c564eba6" ON "django_admin_log" ("user_id");
CREATE UNIQUE INDEX "django_content_type_app_label_model_76bd3d3b_uniq" ON "django_content_type" ("app_label", "model");
CREATE UNIQUE INDEX "auth_permission_content_type_id_codename_01ab375a_uniq" ON "auth_permission" ("content_type_id", "codename");
CREATE INDEX "auth_permission_content_type_id_2f476e4b" ON "auth_permission" ("content_type_id");
CREATE UNIQUE INDEX "core_buildingflat_tower_flat_number_df58674f_uniq" ON "core_buildingflat" ("tower", "flat_number");
CREATE INDEX "core_buildingflat_flat_type_id_7ced0578" ON "core_buildingflat" ("flat_type_id");
CREATE INDEX "core_lead_popup_ad_id_d4b359e1" ON "core_lead" ("popup_ad_id");
CREATE INDEX "django_session_expire_date_a5c62663" ON "django_session" ("expire_date");
DELETE FROM "sqlite_sequence";
COMMIT;
